const GRAMMAR = {"A1":[{"title":"الضمائر الشخصية (Personalpronomen)","explanation":"زي العربي، كل ضمير في الألمانية له تصريف مختلف للفعل. الفرق إن الألمانية عندها ضمير مخصوص لصيغة الاحترام (Sie) بيتصرف زي الجمع.","table":{"headers":["الضمير","بالعربي","مثال"],"rows":[["ich","أنا","Ich bin Ahmed."],["du","أنت (غير رسمي)","Du bist nett."],["er / sie / es","هو / هي / (محايد)","Er ist müde."],["wir","نحن","Wir sind hier."],["ihr","أنتم (غير رسمي)","Ihr seid spät."],["sie / Sie","هم / حضرتك","Sie sind Lehrer."]]},"examples":[{"de":"Ich heiße Sara.","ar":"اسمي سارة."},{"de":"Wie geht es dir?","ar":"إزيك؟ (إزاي حالك؟)"}]},{"title":"تصريف الفعل في المضارع (Präsens)","explanation":"الفعل في صورته الأصلية (المصدر) بينتهي بـ -en زي lernen (يتعلم). لما نصرفه بنشيل -en ونضيف النهاية المناسبة للضمير.","table":{"headers":["الضمير","النهاية","مثال: lernen"],"rows":[["ich","-e","ich lerne"],["du","-st","du lernst"],["er/sie/es","-t","er lernt"],["wir","-en","wir lernen"],["ihr","-t","ihr lernt"],["sie/Sie","-en","sie lernen"]]},"examples":[{"de":"Ich lerne Deutsch.","ar":"أنا بتعلم الألمانية."},{"de":"Er wohnt in Kairo.","ar":"هو ساكن في القاهرة."}]},{"title":"أدوات التعريف: der, die, das","explanation":"كل اسم ألماني له جنس نحوي (مذكر / مؤنث / محايد) لازم تحفظه مع الكلمة نفسها، مفيش قاعدة ثابتة 100% للأسف. der = مذكر، die = مؤنث، das = محايد، والجمع دايماً die.","table":{"headers":["الأداة","الجنس","مثال"],"rows":[["der","مذكر","der Mann (الرجل)"],["die","مؤنث","die Frau (المرأة)"],["das","محايد","das Kind (الطفل)"],["die","جمع (كل الأجناس)","die Kinder (الأطفال)"]]},"examples":[{"de":"Der Tisch ist groß.","ar":"الطاولة كبيرة."},{"de":"Das Buch ist neu.","ar":"الكتاب جديد."}]},{"title":"أدوات الاستفهام (W-Fragen)","explanation":"كل أدوات السؤال في الألمانية بتبدأ بحرف W تقريباً، زي what/where/when بالإنجليزي.","table":{"headers":["الأداة","المعنى"],"rows":[["was","ماذا"],["wer","من"],["wo","أين"],["wann","متى"],["warum","لماذا"],["wie","كيف"]]},"examples":[{"de":"Wie heißt du?","ar":"ما اسمك؟"},{"de":"Wo wohnst du?","ar":"فين ساكن؟"}]}],"A2":[{"title":"الماضي التام (Perfekt)","explanation":"أكتر زمن بيتستخدم في الكلام اليومي عشان يعبر عن حاجة حصلت في الماضي. بيتكون من فعل مساعد (haben أو sein) + الفعل في صورة Partizip II في آخر الجملة.","table":{"headers":["النوع","الفعل المساعد","مثال"],"rows":[["أفعال عادية","haben","Ich habe gegessen (أنا أكلت)"],["أفعال حركة/تغيّر حالة","sein","Ich bin gegangen (أنا رحت)"]]},"examples":[{"de":"Ich habe Deutsch gelernt.","ar":"أنا اتعلمت ألماني."},{"de":"Wir sind nach Berlin gefahren.","ar":"إحنا سافرنا لبرلين."}]},{"title":"الأفعال الناقصة (Modalverben)","explanation":"أفعال بتغيّر معنى الجملة زي الإمكانية أو الإلزام، وبتيجي مع فعل تاني في الآخر بصورة المصدر.","table":{"headers":["الفعل","المعنى"],"rows":[["können","يقدر / يستطيع"],["müssen","لازم / يجب"],["wollen","عايز / يريد"],["dürfen","مسموح له"],["sollen","المفروض / ينبغي"]]},"examples":[{"de":"Ich kann schwimmen.","ar":"أنا أقدر أعوم."},{"de":"Du musst jetzt gehen.","ar":"لازم تمشي دلوقتي."}]},{"title":"حالة المفعول به المباشر (Akkusativ)","explanation":"بتستخدم مع الشيء اللي الفعل بيقع عليه مباشرة، وبتغيّر بس الأداة المذكرة (der تبقى den).","table":{"headers":["الجنس","Nominativ","Akkusativ"],"rows":[["مذكر","der","den"],["مؤنث","die","die (بدون تغيير)"],["محايد","das","das (بدون تغيير)"],["جمع","die","die (بدون تغيير)"]]},"examples":[{"de":"Ich sehe den Mann.","ar":"أنا شايف الراجل."},{"de":"Sie kauft das Buch.","ar":"هي بتشتري الكتاب."}]},{"title":"حالة الجر (Dativ)","explanation":"بتستخدم بعد حروف جر معينة زي mit (مع)، nach (بعد)، bei (عند)، von (من)، zu (إلى).","table":{"headers":["الجنس","Nominativ","Dativ"],"rows":[["مذكر","der","dem"],["مؤنث","die","der"],["محايد","das","dem"],["جمع","die","den (+n)"]]},"examples":[{"de":"Ich helfe dem Kind.","ar":"أنا بساعد الطفل."},{"de":"Wir fahren mit dem Bus.","ar":"إحنا رايحين بالأتوبيس."}]}],"B1":[{"title":"الماضي البسيط (Präteritum)","explanation":"زمن ماضي بيتستخدم أكتر في الكتابة والقصص، لكن أفعال زي sein و haben بتتستخدم بيه حتى في الكلام العادي.","table":{"headers":["الفعل","Präteritum","مثال"],"rows":[["sein","war","Ich war müde (كنت تعبان)"],["haben","hatte","Ich hatte Zeit (كان عندي وقت)"]]},"examples":[{"de":"Es war einmal ein König.","ar":"كان يا ما كان في قديم الزمان ملك."},{"de":"Ich hatte keine Ahnung.","ar":"ملهاش خبر خالص (مكنش عندي فكرة)."}]},{"title":"الجمل الفرعية (Nebensätze: weil, dass, wenn)","explanation":"في الجملة الفرعية، الفعل المتصرف بيروح في آخر الجملة — ده أهم فرق بينها وبين الجملة الأساسية.","table":{"headers":["الأداة","المعنى","مثال"],"rows":[["weil","لأن","..., weil ich krank bin."],["dass","أنّ","Ich glaube, dass er kommt."],["wenn","إذا / لما","Wenn es regnet, bleibe ich zu Hause."]]},"examples":[{"de":"Ich bleibe zu Hause, weil ich krank bin.","ar":"هفضل في البيت لأني تعبان."},{"de":"Ich hoffe, dass du kommst.","ar":"بتمنى إنك تيجي."}]},{"title":"المبني للمجهول (Passiv)","explanation":"بيتكون من werden + الفعل في صورة Partizip II، وبتستخدم لما الفاعل مش مهم أو غير معروف.","table":{"headers":["الزمن","التركيب","مثال"],"rows":[["مضارع","werden + Partizip II","Das Haus wird gebaut."],["ماضي","wurde + Partizip II","Das Haus wurde gebaut."]]},"examples":[{"de":"Das Haus wird gebaut.","ar":"البيت بيتم بناؤه."},{"de":"Die Tür wurde geöffnet.","ar":"الباب اتفتح."}]}],"B2":[{"title":"المتمنى والافتراض (Konjunktiv II)","explanation":"بنستخدم Konjunktiv II علشان نتكلم عن حاجة مش حقيقية أو مستحيلة، أو نتمنى حاجة، أو نطلب بأدب. بيتكون من würde + المصدر لمعظم الأفعال، أو صيغة خاصة للأفعال الشائعة زي sein و haben والأفعال الناقصة.","table":{"headers":["الفعل","Konjunktiv II","مثال"],"rows":[["sein","wäre","Ich wäre froh. (كنت هبقى مبسوط)"],["haben","hätte","Ich hätte gern einen Kaffee. (حابب قهوة من فضلك)"],["können","könnte","Könntest du mir helfen? (ممكن تساعدني؟)"],["باقي الأفعال","würde + مصدر","Ich würde gern reisen. (حابب أسافر)"]]},"examples":[{"de":"Wenn ich Zeit hätte, würde ich dich besuchen.","ar":"لو كان عندي وقت، كنت هزورك."},{"de":"Ich hätte gern die Rechnung, bitte.","ar":"ممكن الفاتورة من فضلك."}]},{"title":"الجمل الموصولة (Relativsätze)","explanation":"الجملة الموصولة بتوصف اسم قبلها باستخدام ضمائر موصولة زي der, die, das (بتتصرف حسب الحالة النحوية زي أداة التعريف تقريباً). الفعل المتصرف بيروح في آخر الجملة زي أي جملة فرعية.","table":{"headers":["الحالة","مذكر","مؤنث","محايد","جمع"],"rows":[["Nominativ","der","die","das","die"],["Akkusativ","den","die","das","die"],["Dativ","dem","der","dem","denen"]]},"examples":[{"de":"Das ist der Mann, der mir geholfen hat.","ar":"ده الراجل اللي ساعدني."},{"de":"Die Frau, die dort steht, ist meine Lehrerin.","ar":"الست اللي واقفة هناك هي مدرّستي."}]},{"title":"تحويل الأفعال إلى أسماء (Nominalisierung)","explanation":"في اللغة الرسمية والكتابية، بيتحول كتير من الأفعال والصفات لأسماء (غالباً بإضافة -ung للفعل أو استخدام المصدر نفسه كاسم محايد). ده بيدي أسلوب أكاديمي أو رسمي أكتر.","table":{"headers":["النوع","مثال فعل","الاسم الناتج"],"rows":[["فعل + ung","untersuchen (يفحص)","die Untersuchung (الفحص)"],["مصدر كاسم محايد","lernen (يتعلم)","das Lernen (التعلّم)"],["صفة + heit/keit","frei (حر)","die Freiheit (الحرية)"]]},"examples":[{"de":"Das Lernen einer neuen Sprache braucht Geduld.","ar":"تعلّم لغة جديدة محتاج صبر."},{"de":"Die Untersuchung dauerte drei Stunden.","ar":"الفحص استغرق ثلاث ساعات."}]},{"title":"حالة الإضافة (Genitiv)","explanation":"الـ Genitiv بتستخدم للملكية أو الإضافة (زي 'بتاع' في العربي)، وبتضيف -s أو -es للاسم المذكر أو المحايد. في الكلام اليومي كتير من الألمان بيستبدلوها بـ von + Dativ.","table":{"headers":["الجنس","الأداة","مثال"],"rows":[["مذكر","des","das Auto des Mannes (سيارة الراجل)"],["مؤنث","der","die Tasche der Frau (شنطة الست)"],["محايد","des","die Farbe des Hauses (لون البيت)"],["جمع","der","die Spielzeuge der Kinder (لعب الأطفال)"]]},"examples":[{"de":"Das ist das Auto meines Bruders.","ar":"دي عربية أخويا."},{"de":"Am Ende des Tages bin ich müde.","ar":"في آخر اليوم بكون تعبان."}]}],"C1":[{"title":"الكلام المنقول (Konjunktiv I)","explanation":"بنستخدم Konjunktiv I علشان ننقل كلام حد تاني (الكلام غير المباشر) في الأخبار والتقارير الرسمية، من غير ما نأكد إحنا لو الكلام صح أو لأ.","table":{"headers":["الضمير","sein","haben","الفعل العادي (زي kommen)"],"rows":[["er / sie / es","sei","habe","komme"]]},"examples":[{"de":"Er sagt, er sei krank.","ar":"هو بيقول إنه (على حد قوله) تعبان."},{"de":"Sie behauptet, sie habe keine Zeit.","ar":"هي بتدّعي إنه معهاش وقت."}]},{"title":"الصفات الممتدة (Erweiterte Partizipialattribute)","explanation":"في اللغة الرسمية والصحفية، بيتحط وصف طويل قبل الاسم بدل جملة موصولة كاملة، وده بيخلي الجملة أقصر لكن أصعب في القراءة لأول وهلة.","table":{"headers":["الصيغة العادية (جملة موصولة)","الصيغة الممتدة"],"rows":[["Der Mann, der gestern angekommen ist.","Der gestern angekommene Mann."]]},"examples":[{"de":"Die von der Regierung geplanten Maßnahmen wurden kritisiert.","ar":"الإجراءات اللي خططتها الحكومة اتنقدت."},{"de":"Das lange erwartete Ergebnis kam gestern.","ar":"النتيجة اللي كنا مستنيينها بقالها وقت طويل جت إمبارح."}]},{"title":"أدوات الربط المتقدمة","explanation":"في المستوى ده بتحتاج أدوات ربط أدق للتعبير عن التناقض، النتيجة، أو الشرط المزدوج، وبتظهر كتير في الكتابة الأكاديمية والمقالات.","table":{"headers":["الأداة","المعنى","مثال"],"rows":[["dennoch","ومع ذلك","Es regnete, dennoch gingen wir spazieren."],["folglich","بالتالي","Er hat nicht gelernt, folglich ist er durchgefallen."],["sowohl...als auch","سواء...أو","Sowohl er als auch sie kommen."],["obwohl / obgleich","رغم أن","Obgleich es schwierig war, hat sie es geschafft."]]},"examples":[{"de":"Sie war müde, dennoch arbeitete sie weiter.","ar":"كانت تعبانة، ومع كده كملت شغل."},{"de":"Er hatte weder Geld noch Zeit.","ar":"ملوش فلوس ولا وقت."}]}],"C2":[{"title":"اللواصق النحوية الدقيقة (Modalpartikeln)","explanation":"دي كلمات صغيرة زي doch, ja, mal, eben, halt بتضيف نبرة أو إحساس للجملة (تعجب، إلحاح، تأكيد) وصعب توصف معناها بكلمة واحدة — لازم تحسها من السياق والاستخدام الكتير.","table":{"headers":["الأداة","الإحساس اللي بتضيفه","مثال"],"rows":[["doch","إلحاح / تعجب","Das weißt du doch! (إنت عارف ده أصلاً!)"],["ja","تأكيد بديهي","Das ist ja klar! (ده واضح طبعاً!)"],["mal","تلطيف الطلب","Komm mal her! (تعال شوية!)"],["halt / eben","استسلام / أمر واقع","Das ist halt so. (كده الوضع بقى)"]]},"examples":[{"de":"Sag mal, wie geht's dir wirklich?","ar":"قولّي، إزيك فعلاً؟"},{"de":"Das ist eben das Leben.","ar":"دي الحياة كده."}]},{"title":"الفرق بين الأسلوب الرسمي والعامي (Register)","explanation":"الألماني الفصيح المكتوب بيختلف كتير عن العامي المنطوق، مش بس في الكلمات لكن في ترتيب الجملة كمان. المستوى ده بيتطلب إنك تعرف تتنقل بين الاتنين حسب الموقف.","table":{"headers":["السياق","مثال رسمي","مقابله العامي"],"rows":[["الاستفسار","Könnten Sie mir bitte helfen?","Kannst du mir helfen?"],["الاعتذار","Ich bedaure den Vorfall zutiefst.","Tut mir echt leid."],["الوداع","Ich verabschiede mich hiermit.","Tschüss, bis später!"]]},"examples":[{"de":"Sehr geehrte Damen und Herren, ...","ar":"السادة المحترمين (بداية خطاب رسمي)..."},{"de":"Hey, alles klar bei dir?","ar":"هاي، عامل إيه؟ (عامي جداً)"}]},{"title":"الجمل الشرطية الثلاثة (Konditionalsätze)","explanation":"الجمل الشرطية في الألماني بتتقسم لثلاث أنواع حسب احتمالية حدوث الشرط: النوع الأول للحقيقي أو الممكن، التاني للمستحيل أو البعيد في الحاضر، والتالت للمستحيل في الماضي.","table":{"headers":["النوع","الزمن","مثال"],"rows":[["النوع 1 (حقيقي)","Präsens","Wenn ich Zeit habe, komme ich."],["النوع 2 (غير حقيقي - حاضر)","Konjunktiv II","Wenn ich Zeit hätte, käme ich."],["النوع 3 (غير حقيقي - ماضي)","Konjunktiv II + Perfekt","Wenn ich Zeit gehabt hätte, wäre ich gekommen."]]},"examples":[{"de":"Wenn ich reich wäre, würde ich die Welt bereisen.","ar":"لو كنت غني، كنت هسافر أطوف الدنيا."},{"de":"Wenn er früher gekommen wäre, hätte er den Zug erwischt.","ar":"لو كان جه بدري، كان لحق القطر."}]}]};
const LISTENING = {"A1":[{"de":"Hallo, wie geht es dir?","ar":"مرحبا، إزيك؟"},{"de":"Ich heiße Ahmed und komme aus Ägypten.","ar":"اسمي أحمد وأنا من مصر."},{"de":"Wie viel Uhr ist es?","ar":"الساعة كام؟"},{"de":"Das ist mein Bruder.","ar":"ده أخويا."},{"de":"Ich möchte einen Kaffee, bitte.","ar":"عايز قهوة من فضلك."},{"de":"Wo ist die Toilette?","ar":"فين الحمام؟"},{"de":"Vielen Dank für Ihre Hilfe.","ar":"شكراً جزيلاً على مساعدتك."},{"de":"Ich verstehe das nicht.","ar":"أنا مش فاهم ده."},{"de":"Können Sie das bitte wiederholen?","ar":"ممكن تعيد ده تاني من فضلك؟"},{"de":"Auf Wiedersehen, bis morgen!","ar":"مع السلامة، لحد بكرة!"}],"A2":[{"de":"Ich habe gestern Deutsch gelernt.","ar":"أنا اتعلمت ألماني إمبارح."},{"de":"Wir sind letztes Jahr nach Berlin gefahren.","ar":"إحنا سافرنا لبرلين السنة اللي فاتت."},{"de":"Kannst du mir bitte helfen?","ar":"ممكن تساعدني من فضلك؟"},{"de":"Ich muss heute früh aufstehen.","ar":"لازم أصحى بدري النهاردة."},{"de":"Das Wetter ist heute sehr schön.","ar":"الجو النهاردة جميل جداً."},{"de":"Ich arbeite von Montag bis Freitag.","ar":"أنا بشتغل من الإتنين لحد الجمعة."},{"de":"Er fährt jeden Tag mit dem Bus zur Arbeit.","ar":"هو بيروح الشغل بالأتوبيس كل يوم."},{"de":"Meine Familie wohnt in Kairo.","ar":"عيلتي ساكنة في القاهرة."}],"B1":[{"de":"Ich glaube, dass Deutsch lernen viel Übung braucht.","ar":"أعتقد إن تعلم الألماني محتاج تدريب كتير."},{"de":"Wenn ich Zeit habe, lese ich gerne Bücher.","ar":"لما بيكون عندي وقت، بحب أقرا كتب."},{"de":"Das Projekt wurde letzte Woche fertiggestellt.","ar":"المشروع اتخلّص الأسبوع اللي فات."},{"de":"Ich würde gerne mehr über die deutsche Kultur erfahren.","ar":"حابب أعرف أكتر عن الثقافة الألمانية."},{"de":"Obwohl es regnete, sind wir spazieren gegangen.","ar":"رغم إنها كانت بتمطر، إحنا مشينا نتفسح."},{"de":"Er hat sich entschieden, in Deutschland zu studieren.","ar":"هو قرر يدرس في ألمانيا."}],"B2":[{"de":"Die Regierung hat gestern neue Maßnahmen zur Bekämpfung der Inflation angekündigt.","ar":"الحكومة أعلنت إمبارح عن إجراءات جديدة لمكافحة التضخم."},{"de":"Obwohl er hart gearbeitet hat, wurde sein Projekt leider abgelehnt.","ar":"رغم إنه اشتغل بجد، للأسف اتم رفض مشروعه."},{"de":"Ich würde gern mehr Verantwortung in meinem Job übernehmen.","ar":"حابب أاخد مسؤولية أكبر في شغلي."},{"de":"Die Studie zeigt, dass immer mehr Menschen von zu Hause aus arbeiten.","ar":"الدراسة بتوضح إن ناس أكتر وأكتر بقت تشتغل من البيت."},{"de":"Wenn ich an deiner Stelle wäre, würde ich den Vertrag noch einmal lesen.","ar":"لو كنت مكانك، كنت هقرا العقد تاني."},{"de":"Es ist wichtig, sowohl beruflich als auch privat ein Gleichgewicht zu finden.","ar":"مهم إنك توازن بين شغلك وحياتك الشخصية."},{"de":"Die Nachfrage nach erneuerbaren Energien steigt kontinuierlich.","ar":"الطلب على الطاقة المتجددة بيزيد باستمرار."}],"C1":[{"de":"Die Auswirkungen des Klimawandels sind mittlerweile in nahezu allen Regionen der Welt spürbar.","ar":"تأثيرات التغيّر المناخي بقت محسوسة دلوقتي في كل مناطق العالم تقريباً."},{"de":"Er behauptet, er habe von den Problemen nichts gewusst.","ar":"هو بيدّعي إنه معرفش بالمشاكل خالص (على حد قوله)."},{"de":"Trotz zahlreicher Warnungen wurde das Projekt fortgesetzt.","ar":"رغم التحذيرات الكتيرة، المشروع كمل."},{"de":"Die im letzten Jahr veröffentlichten Zahlen deuten auf einen deutlichen Rückgang hin.","ar":"الأرقام اللي اتنشرت السنة اللي فاتت بتشير لانخفاض واضح."},{"de":"Man sollte stets zwischen Fakten und persönlichen Meinungen unterscheiden.","ar":"لازم دايماً تفرق بين الحقائق والآراء الشخصية."},{"de":"Je mehr man übt, desto sicherer wird man in der Sprache.","ar":"كل ما تتمرن أكتر، كل ما هتبقى واثق في اللغة أكتر."}],"C2":[{"de":"Die Feinheiten der deutschen Grammatik erschließen sich oft erst nach jahrelanger Übung.","ar":"دقائق قواعد اللغة الألمانية غالباً مبتتضحش إلا بعد سنين من التمرين."},{"de":"Sag mal ehrlich, was hältst du wirklich von diesem Vorschlag?","ar":"قولّي بصراحة، رأيك الحقيقي إيه في الاقتراح ده؟"},{"de":"Das Unternehmen sieht sich mit erheblichen Herausforderungen konfrontiert.","ar":"الشركة بتواجه تحديات كبيرة."},{"de":"Es ist eben nicht immer möglich, jeden zufriedenzustellen.","ar":"مش دايماً ممكن ترضي كل حد، دي طبيعة الأمور."},{"de":"Die Debatte offenbarte tiefgreifende Meinungsverschiedenheiten innerhalb der Partei.","ar":"النقاش كشف عن خلافات جذرية جوه الحزب."}]};
const READING = {"A1":[{"title":"يوم سارة (Ein Tag von Sara)","paragraphs":[{"de":"Sara wacht jeden Morgen um sieben Uhr auf. Sie trinkt einen Kaffee und isst Brot mit Käse.","ar":"سارة بتصحى كل صباح الساعة سبعة. بتشرب قهوة وبتاكل عيش بالجبن."},{"de":"Danach geht sie zur Arbeit. Sie arbeitet in einem Büro in der Stadt.","ar":"بعد كده بتروح الشغل. بتشتغل في مكتب في المدينة."},{"de":"Am Abend kocht sie mit ihrer Familie und sie sehen zusammen fern.","ar":"في المسا بتطبخ مع عيلتها وبيتفرجوا على التلفزيون سوا."}]},{"title":"أسرتي (Meine Familie)","paragraphs":[{"de":"Ich heiße Omar und ich bin zwanzig Jahre alt. Ich wohne mit meiner Familie in Kairo.","ar":"اسمي عمر وعندي عشرين سنة. أنا ساكن مع عيلتي في القاهرة."},{"de":"Meine Mutter heißt Mona und mein Vater heißt Karim. Ich habe eine Schwester.","ar":"أمي اسمها منى وأبويا اسمه كريم. عندي أخت واحدة."},{"de":"Am Wochenende essen wir zusammen und spielen Karten.","ar":"في الويكند بناكل مع بعض ونلعب كوتشينة."}]},{"title":"يوم في السوق (Ein Tag auf dem Markt)","paragraphs":[{"de":"Heute gehe ich mit meiner Mutter auf den Markt. Wir kaufen Obst und Gemüse.","ar":"النهاردة رايح السوق مع أمي. بنشتري فاكهة وخضار."},{"de":"Der Apfel kostet zwei Euro und die Tomaten sind billig.","ar":"التفاح بيتباع بيورهين والطماطم رخيصة."},{"de":"Nach dem Einkaufen trinken wir einen Tee zusammen.","ar":"بعد ما نخلص تسوق، بنشرب شاي مع بعض."}]}],"A2":[{"title":"في المطعم (Im Restaurant)","paragraphs":[{"de":"Ahmed und seine Freunde gehen in ein deutsches Restaurant. Der Kellner bringt die Speisekarte.","ar":"أحمد وأصحابه بيروحوا مطعم ألماني. الجرسون بيجيب المنيو."},{"de":"Ahmed bestellt Schnitzel mit Kartoffeln, und seine Freundin bestellt einen Salat.","ar":"أحمد بيطلب شنيتزل مع بطاطس، وصاحبته بتطلب سلطة."},{"de":"Nach dem Essen bezahlen sie und geben dem Kellner Trinkgeld.","ar":"بعد الأكل بيدفعوا وبيدوا الجرسون إكرامية."}]},{"title":"رحلة إلى الإسكندرية (Ein Ausflug nach Alexandria)","paragraphs":[{"de":"Letztes Wochenende bin ich mit meinen Freunden nach Alexandria gefahren.","ar":"الويكند اللي فات رحت الإسكندرية مع أصحابي."},{"de":"Wir haben das Meer gesehen und frischen Fisch gegessen.","ar":"شفنا البحر وأكلنا سمك طازة."},{"de":"Es war ein schöner Tag, aber die Rückfahrt war sehr lang.","ar":"كان يوم جميل، بس رحلة الرجوع كانت طويلة قوي."}]},{"title":"أول يوم في الشغل (Der erste Arbeitstag)","paragraphs":[{"de":"Heute war mein erster Tag bei der neuen Firma. Ich war ein bisschen nervös.","ar":"النهاردة كان أول يوم ليا في الشركة الجديدة. كنت متوتر شوية."},{"de":"Meine Kollegen waren sehr freundlich und haben mir viel geholfen.","ar":"زمايلي كانوا لطاف قوي وساعدوني كتير."},{"de":"Am Ende des Tages war ich müde, aber auch sehr zufrieden.","ar":"في آخر اليوم كنت تعبان، بس كمان مبسوط قوي."}]}],"B1":[{"title":"رحلة إلى برلين (Eine Reise nach Berlin)","paragraphs":[{"de":"Letzten Sommer bin ich mit meiner Familie nach Berlin gereist. Die Stadt war voller Geschichte und Kultur.","ar":"الصيف اللي فات سافرت مع عيلتي لبرلين. المدينة كانت مليانة تاريخ وثقافة."},{"de":"Wir haben die Berliner Mauer besucht und viel über die deutsche Geschichte gelernt.","ar":"زرنا سور برلين واتعلمنا حاجات كتير عن التاريخ الألماني."},{"de":"Obwohl die Reise kurz war, werde ich sie nie vergessen.","ar":"رغم إن الرحلة كانت قصيرة، مش هنساها أبداً."}]},{"title":"قرار تغيير المهنة (Die Entscheidung, den Beruf zu wechseln)","paragraphs":[{"de":"Nach fünf Jahren als Ingenieurin hat sich Laila entschieden, ihren Beruf zu wechseln.","ar":"بعد خمس سنين شغل مهندسة، ليلى قررت تغيّر مهنتها."},{"de":"Sie wollte schon immer etwas Kreatives machen, deshalb hat sie angefangen, Grafikdesign zu studieren.","ar":"كانت دايماً عايزة تعمل حاجة إبداعية، فبدأت تدرس تصميم جرافيك."},{"de":"Ihre Familie war zuerst besorgt, aber jetzt ist sie stolz auf ihre Entscheidung.","ar":"عيلتها كانت قلقانة الأول، بس دلوقتي فخورة بقرارها."}]},{"title":"التطوع في القرية (Freiwilligenarbeit im Dorf)","paragraphs":[{"de":"Jeden Sommer fährt Youssef in ein kleines Dorf, um dort freiwillig zu arbeiten.","ar":"كل صيف يوسف بيروح قرية صغيرة يشتغل فيها تطوع."},{"de":"Er unterrichtet die Kinder und hilft beim Bau von Schulen.","ar":"بيعلّم الأطفال وبيساعد في بناء مدارس."},{"de":"Diese Erfahrung hat sein Leben komplett verändert.","ar":"التجربة دي غيّرت حياته تماماً."}]}],"B2":[{"title":"تحدي العمل عن بُعد (Die Herausforderung der Fernarbeit)","paragraphs":[{"de":"Seit der Pandemie arbeiten immer mehr Menschen von zu Hause aus. Diese Entwicklung bringt sowohl Vorteile als auch Nachteile mit sich.","ar":"من بعد الجايحة، ناس أكتر وأكتر بقت تشتغل من البيت. التطور ده بيجيب معاه مميزات وعيوب في نفس الوقت."},{"de":"Auf der einen Seite sparen die Angestellten Zeit, weil sie nicht mehr pendeln müssen. Auf der anderen Seite fehlt vielen der direkte Kontakt zu ihren Kollegen.","ar":"من ناحية، الموظفين بيوفروا وقت لأنهم مش محتاجين يتنقلوا كل يوم. من ناحية تانية، كتير منهم بيفتقدوا التواصل المباشر مع زمايلهم."},{"de":"Experten empfehlen deshalb ein hybrides Modell, bei dem man teils zu Hause und teils im Büro arbeitet.","ar":"عشان كده الخبراء بينصحوا بنموذج مختلط، تشتغل فيه جزء من البيت وجزء في المكتب."}]},{"title":"أزمة المياه العالمية (Die globale Wasserkrise)","paragraphs":[{"de":"Weltweit haben immer mehr Menschen keinen Zugang zu sauberem Trinkwasser. Diese Krise betrifft besonders Entwicklungsländer.","ar":"على مستوى العالم، ناس أكتر وأكتر مالهاش وصول لمية شرب نظيفة. الأزمة دي بتأثر بشكل خاص على الدول النامية."},{"de":"Der Klimawandel verschärft das Problem zusätzlich, da Dürreperioden häufiger und intensiver werden.","ar":"التغيّر المناخي بيزوّد المشكلة، لأن فترات الجفاف بقت أكتر وأقوى."},{"de":"Internationale Organisationen fordern deshalb dringende Investitionen in nachhaltige Wassersysteme.","ar":"عشان كده المنظمات الدولية بتطالب باستثمارات عاجلة في أنظمة مياه مستدامة."}]},{"title":"وسائل التواصل الاجتماعي وتأثيرها (Soziale Medien und ihr Einfluss)","paragraphs":[{"de":"Soziale Medien haben die Art, wie wir kommunizieren, grundlegend verändert.","ar":"وسائل التواصل الاجتماعي غيّرت بشكل جذري طريقة تواصلنا."},{"de":"Einerseits ermöglichen sie es, mit Menschen auf der ganzen Welt in Kontakt zu bleiben. Andererseits können sie auch zu Einsamkeit und Vergleichsdruck führen.","ar":"من ناحية، بتسهّل التواصل مع ناس من كل العالم. من ناحية تانية، ممكن تؤدي لشعور بالوحدة وضغط المقارنة."},{"de":"Ein bewusster Umgang mit sozialen Medien ist daher heutzutage besonders wichtig.","ar":"عشان كده التعامل الواعي مع وسائل التواصل الاجتماعي بقى مهم قوي دلوقتي."}]}],"C1":[{"title":"الذكاء الاصطناعي وسوق العمل (Künstliche Intelligenz und der Arbeitsmarkt)","paragraphs":[{"de":"Die rasante Entwicklung der künstlichen Intelligenz verändert zunehmend die Anforderungen an den Arbeitsmarkt. Viele Berufe, die früher als sicher galten, stehen heute vor grundlegenden Veränderungen.","ar":"التطور السريع للذكاء الاصطناعي بيغيّر باستمرار متطلبات سوق العمل. كتير من المهن اللي كانت زمان تعتبر آمنة، بقت النهارده قدام تغيّرات جذرية."},{"de":"Während einige Experten vor einem massiven Stellenabbau warnen, betonen andere, dass neue Berufsfelder entstehen werden, die es heute noch gar nicht gibt.","ar":"في حين إن بعض الخبراء بيحذروا من تسريح واسع للوظايف، بيأكد خبراء تانيين إن مجالات عمل جديدة هتظهر لسه مش موجودة أصلاً دلوقتي."},{"de":"Fest steht jedenfalls, dass lebenslanges Lernen wichtiger denn je geworden ist, um mit dieser Entwicklung Schritt zu halten.","ar":"اللي أكيد على أي حال، إن التعلّم المستمر مدى الحياة بقى أهم من أي وقت مضى عشان تواكب التطور ده."}]},{"title":"أزمة الهوية في عصر العولمة (Identitätskrise im Zeitalter der Globalisierung)","paragraphs":[{"de":"In einer zunehmend globalisierten Welt stellt sich für viele Menschen die Frage nach der eigenen kulturellen Identität neu.","ar":"في عالم بيتعولم أكتر وأكتر، سؤال الهوية الثقافية بقى مطروح من جديد لكتير من الناس."},{"de":"Während einige die kulturelle Vermischung als Bereicherung empfinden, sehen andere darin eine Bedrohung für traditionelle Werte.","ar":"في حين إن بعض الناس بيشوفوا الاندماج الثقافي إثراء، ناس تانية بتشوفه تهديد للقيم التقليدية."},{"de":"Letztlich hängt der Umgang mit dieser Frage stark von individuellen Erfahrungen und gesellschaftlichem Kontext ab.","ar":"في النهاية، طريقة التعامل مع السؤال ده بتعتمد كتير على التجارب الشخصية والسياق المجتمعي."}]},{"title":"تحديات الطاقة المتجددة (Herausforderungen der erneuerbaren Energien)","paragraphs":[{"de":"Obwohl erneuerbare Energien als Lösung für den Klimawandel gelten, stehen ihrer Umsetzung noch zahlreiche Hindernisse im Weg.","ar":"رغم إن الطاقة المتجددة بتعتبر حل للتغيّر المناخي، لسه في عقبات كتيرة قدام تطبيقها."},{"de":"Zu den größten Herausforderungen zählen die hohen Anfangsinvestitionen sowie die Speicherung überschüssiger Energie.","ar":"من أكبر التحديات الاستثمارات الأولية العالية وكمان تخزين الطاقة الزايدة."},{"de":"Dennoch investieren immer mehr Länder in diese Technologien, um langfristig unabhängiger von fossilen Brennstoffen zu werden.","ar":"ومع ذلك، دول أكتر وأكتر بتستثمر في التكنولوجيا دي عشان تبقى أقل اعتماد على الوقود الأحفوري على المدى الطويل."}]}],"C2":[{"title":"بين الهوية واللغة (Zwischen Identität und Sprache)","paragraphs":[{"de":"Sprache ist weit mehr als ein bloßes Kommunikationsmittel; sie prägt maßgeblich die Art und Weise, wie wir die Welt wahrnehmen und unsere Identität konstruieren.","ar":"اللغة أكتر بكتير من مجرد وسيلة تواصل؛ هي بتشكّل بشكل جوهري الطريقة اللي بنشوف بيها العالم وبنبني بيها هويتنا."},{"de":"Wer eine Fremdsprache erlernt, eignet sich nicht nur Vokabeln und Grammatik an, sondern taucht zugleich in eine völlig andere Denkweise ein.","ar":"اللي بيتعلم لغة أجنبية، مش بس بيكتسب مفردات وقواعد، لكنه كمان بيغوص في طريقة تفكير مختلفة تماماً."},{"de":"Insofern lässt sich behaupten, dass jeder neue Sprachschatz gewissermaßen eine Erweiterung der eigenen Persönlichkeit darstellt.","ar":"وبالتالي ممكن نقول إن كل رصيد لغوي جديد بيمثل نوع من التوسّع في شخصية الإنسان نفسه."}]},{"title":"جدلية الحرية والمسؤولية (Die Dialektik von Freiheit und Verantwortung)","paragraphs":[{"de":"Die Frage, inwiefern individuelle Freiheit stets mit gesellschaftlicher Verantwortung einhergehen muss, beschäftigt Philosophen seit Jahrhunderten.","ar":"سؤال إلى أي مدى لازم تكون الحرية الفردية مرتبطة دايماً بمسؤولية مجتمعية، شغل بال الفلاسفة من قرون."},{"de":"Manche Denker argumentieren, dass wahre Freiheit erst durch die Anerkennung ihrer Grenzen entsteht.","ar":"بعض المفكرين بيجادلوا إن الحرية الحقيقية بتتحقق بس لما تعترف بحدودها."},{"de":"Andere wiederum betrachten jegliche Einschränkung als Widerspruch zum Wesen der Freiheit selbst.","ar":"في المقابل، مفكرين تانيين بيشوفوا أي تقييد كتناقض مع جوهر الحرية نفسها."}]},{"title":"الأدب كمرآة للمجتمع (Literatur als Spiegel der Gesellschaft)","paragraphs":[{"de":"Seit jeher dient Literatur nicht nur der Unterhaltung, sondern auch als kritisches Instrument zur Reflexion gesellschaftlicher Zustände.","ar":"من زمان، الأدب مش بس بيسلي، لكنه كمان أداة نقدية للتأمل في أحوال المجتمع."},{"de":"Große Werke der Weltliteratur greifen oft zeitlose Themen wie Macht, Gerechtigkeit und menschliche Schwäche auf.","ar":"الأعمال الأدبية العظيمة غالباً بتتناول مواضيع خالدة زي السلطة والعدالة والضعف الإنساني."},{"de":"Durch die Interpretation dieser Werke gewinnen Leser oft neue Einsichten über ihre eigene Zeit.","ar":"من خلال تفسير الأعمال دي، القراء غالباً بيكتسبوا رؤى جديدة عن زمنهم."}]}]};
const BLOG = [{"icon":"🔤","title":"إزاي تحفظ der, die, das بسهولة؟","summary":"مشكلة كل متعلمي الألماني الأولى — إليك طريقة عملية للتعامل معاها.","content":["مفيش قاعدة سحرية تخليك تعرف جنس كل كلمة ألمانية 100%، لكن فيه استراتيجيات بتقلل الأخطاء كتير.","أول حاجة: اتعلم الكلمة مع أداتها من أول لحظة — يعني متقولش 'Haus' لوحدها، قول 'das Haus'. الدماغ بيربط الاثنين مع بعض كوحدة واحدة.","ثانياً: فيه أنماط بتساعد — مثلاً الكلمات اللي بتنتهي بـ -ung, -heit, -keit, -schaft غالباً مؤنثة (die). والكلمات اللي بتنتهي بـ -chen, -lein غالباً محايدة (das) لأنها تصغير.","ثالثاً: استخدم الألوان في مذكراتك — أزرق للـ der، أحمر للـ die، أخضر للـ das (زي ما عملنا في بطاقات المفردات هنا بالظبط!). التكرار البصري بيثبت المعلومة أسرع."]},{"icon":"🚀","title":"أفضل 5 نصايح لتعلم الألمانية بسرعة","summary":"خطوات عملية جربها متعلمين كتير ونجحت معاهم.","content":["1. اتعلم بالسياق مش بالحفظ الجاف: بدل ما تحفظ قايمة كلمات منفصلة، اتعلمها في جمل — زي البطاقات اللي في قسم المفردات هنا.","2. اسمع ألماني يومياً ولو 10 دقايق بس: بودكاست، أغاني، أو حتى فيديوهات يوتيوب بسيطة. الأذن بتتعود على الإيقاع قبل ما تفهم كل كلمة.","3. اتكلم من أول يوم: متستناش لحد ما 'تبقى جاهز'. غلطك في الكلام هو أسرع طريقة تتعلم بيها.","4. ركّز على أكتر 1000 كلمة استخداماً الأول: دي بتغطي أكتر من 80% من أي كلام يومي عادي.","5. كرر بانتظام مش بكثافة: نص ساعة كل يوم أفضل بكتير من 5 ساعات مرة في الأسبوع."]},{"icon":"⏳","title":"الفرق بين Perfekt و Präteritum","summary":"زمنان للماضي — إمتى تستخدم كل واحد فيهم؟","content":["الـ Perfekt (haben/sein + Partizip II) هو الزمن اللي بتستخدمه في الكلام اليومي العادي عشان تحكي حاجة حصلت. زي: 'Ich habe gegessen' (أنا أكلت).","الـ Präteritum غالباً بتلاقيه في الكتابة، الروايات، والأخبار. بس فيه استثناء مهم: أفعال زي sein و haben و الأفعال الناقصة (modal verbs) بتتستخدم في صورة Präteritum حتى في الكلام العادي — زي 'Ich war müde' مش 'Ich bin müde gewesen'.","نصيحة عملية: ابدأ بالـ Perfekt في كلامك اليومي، وخليك واعي بالـ Präteritum لما تقرا نصوص أو تسمع أخبار."]},{"icon":"⚠️","title":"أخطاء شائعة يقع فيها العرب في الألمانية","summary":"تعرف عليها الأول تقدر تتجنبها بسهولة.","content":["1. ترتيب الفعل: في العربي الفعل بييجي الأول غالباً، لكن في الألماني الفعل المتصرف لازم يكون في المكان التاني في الجملة الأساسية.","2. تجاهل جنس الاسم: كتير من المتعلمين بيهملوا حفظ der/die/das من الأول، وده بيصعّب عليهم قواعد تانية زي الـ Akkusativ والـ Dativ لاحقاً.","3. الخلط بين sie (هي) و Sie (حضرتك) و sie (هم) — الفرق بس في حرف كبير، لكن السياق بيوضحه.","4. نطق حرف 'ch': فيه صوتين مختلفين لـ ch حسب الحرف اللي قبله، وده بياخد وقت يتعود عليه الأذن العربية."]},{"icon":"📊","title":"كام كلمة محتاج تتعلمها عشان توصل B1؟","summary":"أرقام واقعية تساعدك تحدد هدفك.","content":["حسب معايير Goethe Institut، مستوى A1 بيحتاج حوالي 500-600 كلمة أساسية، A2 حوالي 1000-1200 كلمة.","لما توصل B1 (المستوى اللي بيفتحلك فرص الدراسة والشغل في ألمانيا) هتكون محتاج حوالي 2000-2500 كلمة نشطة.","الخبر الكويس: مش لازم تحفظهم كلهم بالحفظ الجامد. لو اتعلمت 15-20 كلمة جديدة كل أسبوع بالسياق والتكرار، هتوصل لـ B1 خلال سنة تقريباً."]}];
